let searchTimeout=null;const SEARCH_DEBOUNCE_MS=300;function initSearch(){const searchInput=document.getElementById('globalSearchInput');const searchResults=document.getElementById('searchResults');if(!searchInput)return;searchInput.addEventListener('input',(e)=>{const query=e.target.value.trim();if(searchTimeout){clearTimeout(searchTimeout);}
if(!query){hideSearchResults();return;}
searchTimeout=setTimeout(()=>{performGlobalSearch(query);},SEARCH_DEBOUNCE_MS);});document.addEventListener('click',(e)=>{if(!e.target.closest('.search-container')){hideSearchResults();}});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'){hideSearchResults();searchInput.blur();}});}
async function performGlobalSearch(query){const searchResults=document.getElementById('searchResults');try{showSearchLoading();const response=await fetch(`/api/search/global?q=${encodeURIComponent(query)}`);const data=await response.json();if(data.success){displaySearchResults(data.results,query);}else{showSearchError(data.error||'搜尋失敗');}}catch(error){console.error('搜尋錯誤:',error);showSearchError('搜尋時發生錯誤');}}
function displaySearchResults(results,query){const searchResults=document.getElementById('searchResults');const{games,members,total}=results;if(total===0){searchResults.innerHTML=`<div class="search-no-results"><p>找不到「${escapeHtml(query)}」的相關結果</p></div>`;searchResults.classList.add('show');return;}
let html='';if(games&&games.length>0){html+='<div class="search-section">';html+=`<div class="search-section-title">🎲 遊戲(${games.length})</div>`;html+='<div class="search-items">';games.slice(0,5).forEach(game=>{const gameName=game.name||'未知遊戲';const gameStatus=game.status||'';const statusClass=gameStatus==='可用'?'available':'borrowed';html+=`<div class="search-item"onclick="window.location.href='/'"><div class="search-item-icon">🎮</div><div class="search-item-content"><div class="search-item-title">${escapeHtml(gameName)}</div><div class="search-item-meta"><span class="status-badge ${statusClass}">${escapeHtml(gameStatus)}</span></div></div></div>`;});if(games.length>5){html+=`<div class="search-more">還有 ${games.length-5}個遊戲...</div>`;}
html+='</div></div>';}
if(members&&members.length>0){html+='<div class="search-section">';html+=`<div class="search-section-title">👥 會員(${members.length})</div>`;html+='<div class="search-items">';members.slice(0,5).forEach(member=>{const memberName=member.name||'未知會員';const memberId=member.id||'';html+=`<div class="search-item"><div class="search-item-icon">👤</div><div class="search-item-content"><div class="search-item-title">${escapeHtml(memberName)}</div><div class="search-item-meta">${escapeHtml(memberId)}</div></div></div>`;});if(members.length>5){html+=`<div class="search-more">還有 ${members.length-5}個會員...</div>`;}
html+='</div></div>';}
searchResults.innerHTML=html;searchResults.classList.add('show');}
function showSearchLoading(){const searchResults=document.getElementById('searchResults');searchResults.innerHTML=`<div class="search-loading"><div class="spinner"></div><p>搜尋中...</p></div>`;searchResults.classList.add('show');}
function showSearchError(message){const searchResults=document.getElementById('searchResults');searchResults.innerHTML=`<div class="search-error"><p>❌ ${escapeHtml(message)}</p></div>`;searchResults.classList.add('show');}
function hideSearchResults(){const searchResults=document.getElementById('searchResults');if(searchResults){searchResults.classList.remove('show');}}
function escapeHtml(text){const div=document.createElement('div');div.textContent=text;return div.innerHTML;}
document.addEventListener('DOMContentLoaded',initSearch);